Tailwind Marquee accepts children and HTML div attributes plus pauseOnHover, repeat, reverse, vertical, duration and gap. Defaults are false, 4, false, false, 40 seconds and 1rem. The example uses 20 seconds for its first row and reverses the second row.

Documented SolidJS example:
```tsx
import { cn } from "@/lib/utils";
import { Marquee } from "@/ui/marquee";
import { For } from "solid-js";

const reviews = [
	{
		name: "Jack",
		username: "@jack",
		body: "I've never seen anything like this before. It's amazing. I love it.",
		img: "https://avatar.vercel.sh/jack",
	},
	{
		name: "Jill",
		username: "@jill",
		body: "I don't know what to say. I'm speechless. This is amazing.",
		img: "https://avatar.vercel.sh/jill",
	},
	{
		name: "John",
		username: "@john",
		body: "I'm at a loss for words. This is amazing. I love it.",
		img: "https://avatar.vercel.sh/john",
	},
];

const ReviewCard = ({
	img,
	name,
	username,
	body,
}: {
	img: string;
	name: string;
	username: string;
	body: string;
}) => {
	return (
		<figure
			class={cn(
				"relative w-64 cursor-pointer overflow-hidden rounded-xl border p-4",
				// light styles
				"border-gray-950/[.1] bg-gray-950/[.01] hover:bg-gray-950/[.05]",
				// dark styles
				"dark:border-gray-50/[.1] dark:bg-gray-50/[.10] dark:hover:bg-gray-50/[.15]",
			)}
		>
			<div class="flex flex-row items-center gap-2">
				<img
					class="rounded-full"
					width="32"
					height="32"
					alt="avatar-img"
					src={img}
				/>
				<div class="flex flex-col">
					<span class="text-sm font-medium dark:text-white">{name}</span>
					<p class="text-xs font-medium dark:text-white/40">{username}</p>
				</div>
			</div>
			<blockquote class="mt-2 text-sm">{body}</blockquote>
		</figure>
	);
};

export default function MarqueeDemo() {
	return (
		<div class="relative overflow-hidden">
			<Marquee pauseOnHover duration={20}>
				<For each={reviews}>{(review) => <ReviewCard {...review} />}</For>
			</Marquee>
			<Marquee reverse pauseOnHover>
				<For each={reviews}>{(review) => <ReviewCard {...review} />}</For>
			</Marquee>
			<div class="pointer-events-none absolute inset-y-0 left-0 w-1/3 bg-gradient-to-r from-white dark:from-background" />
			<div class="pointer-events-none absolute inset-y-0 right-0 w-1/3 bg-gradient-to-l from-white dark:from-background" />
		</div>
	);
}

```

